// When these texts last actually changed. A real date, edited with the text — the header
// used `new Date()`, so every one of these pages claimed to have been updated today, every
// day, whatever it said. On a policy page that is the one line a reader uses to decide
// whether the terms they agreed to are still the terms in front of them.
const LEGAL_UPDATED = '2026-08-20';

// ── Rendering a policy ───────────────────────────────────────────────────────
//
// The text is authored as plain strings on purpose — there is no markdown parser in the
// path, so nothing here can misread a policy and render it as something it does not say.
// What follows is the smallest amount of structure that makes it READ like a legal
// document instead of a wall: a run of `· ` lines is a list, a run of `1. ` or `a. ` lines
// is an ordered list, and everything else stays a paragraph. Any line that does not match
// falls through unchanged rather than being dropped.

// Two or more consecutive ALL-CAPS words become emphasis. Authored that way throughout —
// "ALL THREE", "HAS BEEN NOTIFIED", "FOURTEEN DAYS" — and left as literal capitals it reads
// as shouting. Each token must be at least two capitals, so a lone acronym followed by a
// capitalised word ("DSA Article 16") is NOT swept up: `Article` contributes only `A`, which
// is one character and fails the rule.
const CAPS_RUN = /(\p{Lu}[\p{Lu}\d’'-]+(?:\s+\p{Lu}[\p{Lu}\d’'-]+)+)/gu;

function Emphasised({ text }) {
  const parts = String(text).split(CAPS_RUN);
  return parts.map((s, i) => (
    // The odd indices are the captured runs. Emphasis is a colour change and a weight, not
    // a different size: a legal page where phrases jump around in scale reads as a flyer.
    i % 2 ? <strong key={i} className="font-semibold text-[var(--text)]">{s}</strong> : <span key={i}>{s}</span>
  ));
}

const BULLET = /^·\s+/;
const NUM = /^(\d{1,2})\.\s+/;
const ALPHA = /^([a-z])\.\s+/;

function LegalParagraph({ text }) {
  const lines = String(text).split('\n');
  const blocks = [];
  for (const line of lines) {
    const kind = BULLET.test(line) ? 'ul' : NUM.test(line) ? 'ol' : ALPHA.test(line) ? 'oa' : 'p';
    const content = line.replace(BULLET, '').replace(NUM, '').replace(ALPHA, '');
    const last = blocks[blocks.length - 1];
    // A paragraph never merges with the one before it — only list items group, because two
    // adjacent prose lines inside one entry are a deliberate line break, not one sentence.
    if (last && last.kind === kind && kind !== 'p') last.items.push(content);
    else blocks.push({ kind, items: [content] });
  }
  return blocks.map((b, i) => {
    if (b.kind === 'p') {
      return b.items.map((s, k) => (
        <p key={`${i}-${k}`} className="text-[var(--muted)] leading-relaxed mb-3 last:mb-0">
          {s ? <Emphasised text={s} /> : <br />}
        </p>
      ));
    }
    const Tag = b.kind === 'ul' ? 'ul' : 'ol';
    return (
      <Tag key={i}
        className={`mb-3 last:mb-0 space-y-1.5 text-[var(--muted)] leading-relaxed ${
          b.kind === 'ul' ? 'list-disc' : b.kind === 'oa' ? 'list-[lower-alpha]' : 'list-decimal'
        } pl-5 marker:text-[var(--primary-2)]`}>
        {b.items.map((s, k) => <li key={k}><Emphasised text={s} /></li>)}
      </Tag>
    );
  });
}

export function Legal({ page }) {
  const { lang, t } = useI18n();
  const builtIn = (LEGAL[lang] || LEGAL.en)[page];
  const summary = (LEGAL_SUMMARY[lang] || LEGAL_SUMMARY.en)[page];

  // Database first, built-in defaults otherwise — per DOCUMENT, never mixed. A page
  // assembled half from the database and half from the code is one nobody can diff, and the
  // failure would be invisible: it would just quietly say two different things.
  //
  // `null` means "not asked yet" and is deliberately distinct from `{}` ("asked, nothing
  // there"). Rendering the built-in text during the fetch and then swapping it would show a
  // reader one policy and then another, which on this page is worse than a blank moment.
  const [remote, setRemote] = useState(null);
  useEffect(() => {
    let alive = true;
    api.get('/legal').then((r) => { if (alive) setRemote(r?.docs || {}); })
      // A failed fetch falls back to the built-in text rather than to an error: the policy
      // in the bundle is a correct policy, just possibly an older one.
      .catch(() => { if (alive) setRemote({}); });
    return () => { alive = false; };
  }, []);

  const override = remote?.[page];
  const d = override
    ? {
      icon: builtIn.icon,
      title: builtIn.title,
      body: override.sections.map((sec) => [
        (lang === 'fr' && sec.titleFr) || sec.title,
        (lang === 'fr' && sec.bodyFr) || sec.body,
      ]),
      markdown: true,
    }
    : builtIn;
  // Once a document is database-backed its own newest edit is the honest date; the constant
  // would freeze at whatever the source file last said while the text kept changing.
  const updated = override?.updatedAt ? String(override.updatedAt).slice(0, 10) : LEGAL_UPDATED;
  // Which section you are actually reading. A 32-entry contents list with nothing marked is
  // a list you have to re-find your place in every time you glance at it.
  const [active, setActive] = useState(0);
  useEffect(() => {
    const secs = Array.from(document.querySelectorAll('section[id^="s"]'));
    if (!secs.length) return undefined;
    const io = new IntersectionObserver((entries) => {
      // The topmost section currently on screen wins. Taking "the last one that intersected"
      // makes the marker jump backwards when you scroll up past a short section.
      const vis = entries.filter((e) => e.isIntersecting)
        .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
      if (vis) setActive(Number(vis.target.id.slice(1)));
    }, { rootMargin: '-80px 0px -70% 0px' });
    secs.forEach((s) => io.observe(s));
    return () => io.disconnect();
  }, [page, lang]);
  const tabs = [['about', t('foot.about', 'About'), Sparkles], ['privacy', t('foot.privacy'), Lock], ['terms', t('foot.terms'), ShieldCheck], ['cookies', t('foot.cookies'), Cookie], ['refunds', t('foot.refunds', 'Payments'), Receipt]];
  return (
    <div className="max-w-4xl mx-auto" id="legal-print">
      <PageHeader icon={d.icon} title={d.title} subtitle={`${lang === 'fr' ? 'Mis à jour le' : 'Last updated'} ${new Date(`${updated}T00:00:00`).toLocaleDateString()}`} />
      <div className="flex flex-wrap gap-2 mb-5 print:hidden"><Link to="/legal"><Button size="sm" variant="default"><FileText size={14} /> {t('legal.all', 'All')}</Button></Link>{tabs.map(([k, l, I]) => <Link key={k} to={`/legal/${k}`}><Button size="sm" variant={k === page ? 'primary' : 'default'}><I size={14} /> {l}</Button></Link>)}</div>
      {/* plain-language summary */}
      <Card className="p-4 mb-6 flex items-start gap-3 bg-gradient-to-r from-[var(--primary)]/10 to-transparent print:border print:bg-none">
        <d.icon size={18} className="text-[var(--primary-2)] mt-0.5 shrink-0" />
        <div className="text-sm text-[var(--muted)]">{summary}</div>
      </Card>
      <div className="grid md:grid-cols-[180px_1fr] gap-8">
        {/* Its own scroll region with a max height: a 32-entry contents list that is itself
            taller than the window cannot be used to navigate, which is the one job it has. */}
        <nav className="hidden md:block sticky top-20 self-start space-y-0.5 max-h-[calc(100vh-7rem)] overflow-y-auto pr-1 print:hidden">
          <div className="text-[10px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-1.5">{lang === 'fr' ? 'Sur cette page' : 'On this page'}</div>
          {d.body.map(([h], i) => (
            <a key={h} href={`#s${i}`}
              className={`block text-sm py-1 border-l pl-2 -ml-px transition-colors ${
                active === i
                  ? 'text-[var(--primary-2)] border-[var(--primary)] font-medium'
                  : 'text-[var(--muted)] border-transparent hover:text-[var(--primary-2)] hover:border-[var(--primary)]'
              }`}>{h}</a>
          ))}
        </nav>
        <Card className="p-6 md:p-8 space-y-8">
          {d.body.map(([h, p], i) => (
            <section id={`s${i}`} key={h} className="scroll-mt-24 group">
              <h2 className="text-lg font-semibold mb-2.5 flex items-baseline gap-2.5">
                <span className="text-[var(--primary-2)] font-mono text-xs tabular-nums shrink-0">{String(i + 1).padStart(2, '0')}</span>
                <span>{h}</span>
                {/* A permalink per section. People CITE these — "clause 14 of your terms" is
                    unusable, a link is not. Hidden until hover so it does not clutter, but
                    it is a real anchor, so keyboard focus reveals it too. */}
                <a href={`#s${i}`} aria-label={lang === 'fr' ? 'Lien vers cette section' : 'Link to this section'}
                  className="opacity-0 group-hover:opacity-100 focus:opacity-100 text-[var(--faint)] hover:text-[var(--primary-2)] transition-opacity text-sm print:hidden">#</a>
              </h2>
              {/* Blank lines separate entries; inside one, a run of `· ` or `1. ` lines
                  becomes a real list. See LegalParagraph — no markdown parser is involved,
                  so nothing here can misread a policy and render it wrong. */}
              {d.markdown
                ? <div className="legal-md"><Markdown>{String(p)}</Markdown></div>
                : String(p).split('\n\n').map((para, k) => <LegalParagraph key={k} text={para} />)}
            </section>
          ))}
          <div className="pt-5 border-t border-[var(--line)] text-sm text-[var(--muted)] flex flex-wrap items-center justify-between gap-3">
            <span>{lang === 'fr' ? 'Des questions sur cette politique ? Contactez-nous via les liens du pied de page.' : 'Questions about this policy? Reach us via the links in the footer.'}</span>
            {/* Legal pages get saved and filed. print:hidden everywhere else keeps the
                printed copy to the document itself. */}
            <Button size="sm" variant="ghost" onClick={() => window.print()} className="print:hidden">
              <Printer size={13} /> {lang === 'fr' ? 'Imprimer' : 'Print'}
            </Button>
          </div>
        </Card>
      </div>
    </div>
  );
}


// A published version, exactly as it was when it was published.
//
// The admin screen linked here before this existed, so the link 404'd — the archive was a
// promise with nothing behind it. This is the page that makes `termsVersion` mean something:
// somebody who accepted v2 can read v2.
//
// It renders the SNAPSHOT and never the live sections, which is the entire point, and it says
// so on the page rather than leaving a reader to assume they are looking at the current text.
export function LegalArchive() {
  const { id } = useParams();
  const { lang, t } = useI18n();
  const [v, setV] = useState(undefined);   // undefined = loading, null = not found
  useEffect(() => {
    let alive = true;
    api.get(`/legal/versions/${id}`)
      .then((r) => { if (alive) setV(r); })
      .catch(() => { if (alive) setV(null); });
    return () => { alive = false; };
  }, [id]);

  if (v === undefined) return <div className="max-w-4xl mx-auto py-16"><Loading /></div>;
  if (v === null) {
    return (
      <div className="max-w-4xl mx-auto">
        <PageHeader icon={History} title={t('la.gone.t', 'Version not found')}
          subtitle={t('la.gone.s', 'This archived version does not exist, or its link is wrong.')} />
        <Link to="/legal"><Button size="sm"><ArrowLeft size={14} /> {t('la.back', 'All policies')}</Button></Link>
      </div>
    );
  }

  const sections = Array.isArray(v.sections) ? v.sections : [];
  const when = new Date(v.publishedAt).toLocaleDateString();
  const DOC_LABEL = {
    privacy: lang === 'fr' ? 'Confidentialité' : 'Privacy Policy',
    terms: lang === 'fr' ? 'Conditions' : 'Terms of Service',
    cookies: lang === 'fr' ? 'Cookies' : 'Cookie Policy',
    about: lang === 'fr' ? 'À propos' : 'About',
    refunds: lang === 'fr' ? 'Paiements & remboursements' : 'Payments & Refunds',
  };

  return (
    <div className="max-w-4xl mx-auto" id="legal-print">
      <PageHeader icon={History} title={`${DOC_LABEL[v.doc] || v.doc} — v${v.version}`}
        subtitle={`${lang === 'fr' ? 'Publié le' : 'Published'} ${when}`} />

      {/* An archived page that looks like the live one is a trap: somebody lands here from a
          search result and reads a superseded policy as current. The banner is not decoration. */}
      <Card className="p-4 mb-6 border-[var(--ring)]" style={{ background: 'color-mix(in srgb, var(--warning) 8%, transparent)' }}>
        <div className="flex items-start gap-3">
          <History size={18} className="text-[var(--warning)] shrink-0 mt-0.5" />
          <div className="text-sm">
            <div className="font-medium mb-1">{t('la.banner.t', 'This is an archived version')}</div>
            <p className="text-[var(--muted)] mb-2">
              {t('la.banner.d', 'Frozen when it was published and never edited since. It is kept so anyone who accepted this version can read exactly what they accepted. It may not be what applies today.')}
            </p>
            {v.note && <p className="text-[var(--muted)] mb-2"><span className="font-medium">{t('la.note', 'What changed')}:</span> {v.note}</p>}
            <Link to={`/legal/${v.doc}`} className="print:hidden">
              <Button size="sm"><ArrowRight size={14} /> {t('la.current', 'Read the current version')}</Button>
            </Link>
          </div>
        </div>
      </Card>

      <Card className="p-6 md:p-8 space-y-8">
        {sections.map((sec, i) => (
          <section key={i} className="scroll-mt-24">
            <h2 className="text-lg font-semibold mb-2.5 flex items-baseline gap-2.5">
              <span className="text-[var(--primary-2)] font-mono text-xs tabular-nums shrink-0">{String(i + 1).padStart(2, '0')}</span>
              <span>{(lang === 'fr' && sec.titleFr) || sec.title}</span>
            </h2>
            <div className="legal-md"><Markdown>{String((lang === 'fr' && sec.bodyFr) || sec.body || '')}</Markdown></div>
          </section>
        ))}
        <div className="pt-5 border-t border-[var(--line)] text-sm text-[var(--muted)] flex flex-wrap items-center justify-between gap-3">
          <span>{t('la.foot', 'Archived version {v}, published {d}.').replace('{v}', `v${v.version}`).replace('{d}', when)}</span>
          <Button size="sm" variant="ghost" onClick={() => window.print()} className="print:hidden">
            <Printer size={13} /> {lang === 'fr' ? 'Imprimer' : 'Print'}
          </Button>
        </div>
      </Card>
    </div>
  );
}

// The /legal hub — lists every legal/policy document.
export function LegalIndex() {
  const { lang, t } = useI18n();
  const L = LEGAL[lang] || LEGAL.en;
  const S = LEGAL_SUMMARY[lang] || LEGAL_SUMMARY.en;
  const pages = ['about', 'privacy', 'terms', 'cookies', 'refunds'];
  return (
    <div className="max-w-4xl mx-auto">
      <PageHeader icon={FileText} title={t('legal.title', 'Legal & policies')} subtitle={t('legal.sub', 'Our policies and terms, in plain language.')} />
      <div className="grid sm:grid-cols-2 gap-4">
        {pages.map((k) => { const d = L[k]; const I = d.icon; return (
          <Link key={k} to={`/legal/${k}`} className="card card-hover p-5 flex items-start gap-3">
            <span className="grid place-items-center w-10 h-10 rounded-xl bg-[var(--surface-2)] text-[var(--primary-2)] shrink-0"><I size={18} /></span>
            <div className="min-w-0"><div className="font-semibold">{d.title}</div><div className="text-sm text-[var(--muted)] mt-0.5 line-clamp-2">{S[k]}</div></div>
          </Link>
        ); })}
      </div>
    </div>
  );
}
